package com.hobbycoders.aishuffle.net

import com.hobbycoders.aishuffle.model.Server
import java.util.concurrent.ConcurrentHashMap
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

/** Never expose a replacement credential through an autogenerated toString. */
internal class RenewedDeviceKey(val value: String)

/** One in-flight renewal per worker; only durably stored keys reach consumers.
 * Lost responses and failed persistence leave the old saved credential intact,
 * so the worker's bounded renewal receipt can recover the same replacement.
 */
internal class DeviceKeyRenewal(
    private val read: (String) -> Server?,
    private val replace: (Server, String) -> Server?,
    private val exchange: suspend (Server) -> ApiResult<RenewedDeviceKey>,
    private val now: () -> Long = ApiClient::monotonicMillis,
) {
    private val locks = ConcurrentHashMap<String, Mutex>()
    private val checked = ConcurrentHashMap<String, Pair<String, Long>>()

    suspend fun prepare(snapshot: Server): ApiResult<Server> = locks.getOrPut(snapshot.id) { Mutex() }.withLock {
        val current = runCatching { read(snapshot.id) }.getOrNull()
        if (current == null || !sameIdentity(current, snapshot))
            return@withLock ApiResult.Failure("The account or worker changed. Open this worker again.")
        if (current.apiKey.isBlank())
            return@withLock ApiResult.Failure("Authorize this phone for the worker before connecting.")
        val last = checked[current.id]
        if (last != null && last.first == current.apiKey && now() - last.second in 0 until CHECK_INTERVAL_MS)
            return@withLock ApiResult.Success(current)
        val first = exchange(current)
        // Exactly one retry for an interrupted response/outage. Never retry a
        // pending, denied, expired or otherwise rejected credential here.
        val result = if (first is ApiResult.Failure && (first.statusCode == null || first.statusCode >= 500))
            exchange(current) else first
        when (result) {
            is ApiResult.Success -> {
                val replacement = result.data.value
                val saved = runCatching { replace(current, replacement) }.getOrNull()
                    ?: return@withLock ApiResult.Failure("Could not save this worker's renewed credential. Retry before its old key expires.")
                checked[saved.id] = saved.apiKey to now()
                ApiResult.Success(saved)
            }
            is ApiResult.Failure -> result
            ApiResult.NeedsCfAccess -> ApiResult.NeedsCfAccess
        }
    }

    companion object {
        internal const val CHECK_INTERVAL_MS = 6 * 60 * 60 * 1000L
        internal fun sameAuthorization(a: Server, b: Server?): Boolean = b != null && sameIdentity(a, b) &&
            a.authorizationEpoch == b.authorizationEpoch && a.cfAccessClientId == b.cfAccessClientId &&
            a.cfAccessClientSecret == b.cfAccessClientSecret

        internal fun sameIdentity(a: Server, b: Server): Boolean = a.id == b.id &&
            a.baseUrl == b.baseUrl && a.deviceId == b.deviceId && a.accountId == b.accountId &&
            a.hubUrl == b.hubUrl && a.hubServerId == b.hubServerId
    }
}
